package com.aoo.bcg.common.cache;
import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RedisAtomicKeyMigrationTest{static class AtomicFake implements RedisScriptExecutor{Map<String,String>data=new HashMap<>(Map.of("prod:game:{room-1}:v1","old"));public synchronized long eval(String script,List<String>keys,List<String>args){if(data.containsKey(keys.get(1)))return 0;if(!data.containsKey(keys.get(0)))return-1;data.put(keys.get(1),data.remove(keys.get(0)));return 1;}}@Test void oneConcurrentCallerMigratesAndNeverOverwritesTarget()throws Exception{var fake=new AtomicFake();var migration=new RedisAtomicKeyMigration(fake);var pool=Executors.newFixedThreadPool(8);var wins=new AtomicInteger();List<Future<?>>jobs=new ArrayList<>();for(int i=0;i<100;i++)jobs.add(pool.submit(()->{if(migration.migrate("prod:game:{room-1}:v1","prod:game:{room-1}:v2",Duration.ofHours(1))==1)wins.incrementAndGet();}));for(var job:jobs)job.get();pool.shutdown();assertEquals(1,wins.get());assertEquals("old",fake.data.get("prod:game:{room-1}:v2"));assertThrows(IllegalArgumentException.class,()->migration.migrate("prod:{one}:a","prod:{two}:b",Duration.ofSeconds(1)));assertTrue(RedisAtomicKeyMigration.LUA.contains("PTTL"));assertTrue(RedisAtomicKeyMigration.LUA.indexOf("RESTORE")<RedisAtomicKeyMigration.LUA.indexOf("DEL"));}}
